from itertools import islice, count

def chunked_even(iterable, n, min_buffer):
    iterable = iter(iterable)
    buffer = list(islice(iterable, min_buffer))
    for _ in islice(map(buffer.append, iterable), n, None, n):
        yield buffer[:n]
        del buffer[:n]
    if not buffer:
        return
    length = len(buffer)
    q, r = divmod(length, n)
    num_lists = q + (1 if r > 0 else 0)
    q, r = divmod(length, num_lists)
    full_size = q + (1 if r > 0 else 0)
    partial_size = full_size - 1
    num_full = length - partial_size * num_lists
    partial_start_idx = num_full * full_size
    if full_size > 0:
        for i in range(0, partial_start_idx, full_size):
            yield buffer[i : i + full_size]
    if partial_size > 0:
        for i in range(partial_start_idx, length, partial_size):
            yield buffer[i : i + partial_size]

def check(mb_fn, name):
    for N in range(1, 60):
        for n in range(1, N + 2):
            mb = mb_fn(n)
            assert mb >= 0, (name, n, mb)
            lengths, items = [], []
            for l in chunked_even(range(N), n, mb):
                L = len(l)
                assert 1 <= L <= n, (name, N, n, L)
                lengths.append(L); items.extend(l)
            assert items == list(range(N)), (name, N, n)
            assert max(lengths) - min(lengths) <= 1, (name, N, n, lengths)
    for n in range(1, 6):
        k = 0
        def gen():
            for i in count():
                assert i <= (k + 1) * n + n * n, (name, n, k, i)
                yield i
        ls = chunked_even(gen(), n, mb_fn(n))
        while k < 5:
            assert next(ls) == list(range(k*n, (k+1)*n)), (name, n, k)
            k += 1
    print(name, 'OK')

check(lambda n: (n-1)*(n-2), '(n-1)(n-2)')
check(lambda n: max(0,(n+1)*(n-2)), 'max0')
