from itertools import repeat
from more_itertools import interleave, chunked, flatten, islice
# candidate fix for n != 1 branch
def intersperse(e, iterable, n=1):
    if n == 0:
        raise ValueError
    elif n != 1:
        return flatten(islice(interleave(repeat(e), chunked(iterable, n)), 1, None))
    else:
        filler = repeat([e])
        chunks = chunked(iterable, n)
        return flatten(islice(interleave(filler, chunks), 1, None))
print(list(intersperse('_', range(6), n=2)))
print(list(intersperse('!', [1,2,3,4,5])))
print(list(intersperse(None, [1,2,3,4,5], n=2)))
print(list(intersperse('x', range(7), n=3)))
